          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Heart rate"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 76,
          "unit": "beats/min"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Respiratory rate"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 14,
          "unit": "breaths/min"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Body temperature"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 36.7,
          "unit": "°C"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Oxygen saturation on room air"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 99,
          "unit": "%"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Body mass index"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Approximately 24"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Reported right wrist lump and symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Known right dorsal wrist ganglion diagnosed by a previous GP approximately 6–9 months ago; patient unsure of the timing, saying it may have been earlier this year or last year. Lump fluctuates in size and increases after a big day on the computer. Dull ache with occasional sharp twinge on extension, pain up to 5/10, especially at the end of the day. Interferes with typing and mouse work. Patient wondered whether phone use or coffee made it grow and was reassured that these were not related. No night pain or rest pain. No trauma reported, although patient later said they might have knocked it at the gym. No numbness, tingling, weakness, or dropping objects."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Right wrist examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Approximately 1.5–2 cm soft, fluctuant swelling on the dorsal right wrist over the scapholunate area. Non-erythematous and non-warm, with mild tenderness to palpation and discomfort only at end-range extension. Full flexion and extension with slight pain at terminal extension. Neurovascularly intact: good capillary refill, radial pulse present, sensation intact in median, ulnar, and radial distributions, and normal grip."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Right wrist associated red-flag symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient denies redness, warmth, fevers, weight loss, and night sweats."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Left wrist examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Within normal limits."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Consultation behavior and history reliability"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Poor historian regarding timelines and prior treatment; contradicted self regarding imaging and allergies and required repeated clarification. Engaged appropriately once information was simplified."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "unknown",
        "medicationCodeableConcept": {
          "text": "Naproxen"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "500 mg twice daily as needed for wrist pain",
            "asNeededBoolean": true,
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 500,
                  "unit": "mg"
                }
              }
            ],
            "timing": {
              "repeat": {
                "frequency": 2,
                "period": 1,
                "periodUnit": "d"
              }
            }
          }
        ],
        "note": [
          {
            "text": "Listed as a previous medication per EMR; current use is not stated."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Naproxen 500 mg tablets"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "Take one tablet twice daily as needed for wrist pain, with food; maximum 10 days in a row.",
            "asNeededBoolean": true,
            "timing": {
              "repeat": {
                "frequency": 2,
                "period": 1,
                "periodUnit": "d"
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 500,
                  "unit": "mg"
                }
              }
            ]
          }
        ],
        "dispenseRequest": {
          "quantity": {
            "value": 15,
            "unit": "tablets"
          },
          "numberOfRepeatsAllowed": 0
        }
      }
    }
  ]
}
